import { loadFromGitHub } from 'gowm';

// Load compress module
const compress = await loadFromGitHub('benoitpetit/wasm-modules-repository', {
  path: 'compress-wasm',
  name: 'compress-wasm',
  branch: 'master'
});

// Configure for production use
compress.call('setSilentMode', true);

// Gzip compression
const data = 'Hello World! '.repeat(100);
const compressed = compress.call('gzipCompress', data, 9);
console.log('Original size:', compressed.originalSize);
console.log('Compressed size:', compressed.compressedSize);
console.log('Ratio:', compressed.compressionRatio);

// Gzip decompression
const decompressed = compress.call('gzipDecompress', compressed.data);
console.log('Decompressed:', decompressed === data); // true

// Compare all compression algorithms
const jsonData = JSON.stringify({ users: Array(100).fill({ name: 'John', age: 30, email: 'john@example.com' }) });

// Full analysis across all algorithms
const analysis = compress.call('analyzeCompression', jsonData);
console.log('Original size:', analysis.originalSize);
console.log('Data type:', analysis.dataType);
console.log('Entropy:', analysis.entropy);
console.log('Compressibility:', analysis.compressibility);
console.log('Best algorithm:', analysis.bestAlgorithm);
console.log('Best ratio:', analysis.bestRatio);
console.log('Recommendation:', analysis.recommendation);

// View per-algorithm results
analysis.algorithms.forEach(algo => {
  console.log(`${algo.algorithm}: ${algo.compressedSize} bytes (${algo.ratio}, savings: ${algo.savings})`);
});

// Quick estimation without full compression
const estimate = compress.call('estimateCompression', jsonData);
console.log('Estimated ratio:', estimate.estimatedRatio);
console.log('Recommendation:', estimate.recommendation);

// Create a ZIP archive with multiple files
const files = {
  'readme.txt': 'This is a readme file with important information.',
  'data.json': JSON.stringify({ key: 'value', items: [1, 2, 3] }),
  'config.yaml': 'server:\n  port: 8080\n  host: localhost'
};

// Create compressed ZIP
const zip = compress.call('zipCreate', files, true);
console.log('Archive size:', zip.archiveSize);
console.log('Files:', zip.files);
console.log('Compression ratio:', zip.compressionRatio);

// List files without extracting
const listing = compress.call('zipList', zip.data);
listing.entries.forEach(entry => {
  console.log(`${entry.name}: ${entry.originalSize} → ${entry.storedSize} bytes`);
});

// Extract all files
const extracted = compress.call('zipExtract', zip.data);
console.log('Extracted files:', extracted.fileList);
console.log('Content:', extracted.files['readme.txt']);

// Create a TAR archive
const tarFiles = {
  'src/index.js': 'console.log("hello");',
  'src/utils.js': 'export function add(a, b) { return a + b; }',
  'package.json': '{"name": "my-project", "version": "1.0.0"}'
};

// Create TAR archive
const tar = compress.call('tarCreate', tarFiles);
console.log('Archive size:', tar.archiveSize);
console.log('Total size:', tar.totalSize);

// List contents
const tarListing = compress.call('tarList', tar.data);
tarListing.entries.forEach(entry => {
  console.log(`${entry.name}: ${entry.size} bytes`);
});

// Extract
const tarExtracted = compress.call('tarExtract', tar.data);
console.log('Files:', tarExtracted.fileList);

// Multi-algorithm compression comparison
const testData = 'The quick brown fox jumps over the lazy dog. '.repeat(1000);

// Compress with different algorithms
const gzipResult = compress.call('gzipCompress', testData, 9);
const deflateResult = compress.call('deflateCompress', testData, 9);
const lz4Result = compress.call('lz4Compress', testData);
const snappyResult = compress.call('snappyCompress', testData);

console.log('Algorithm comparison:');
console.log(`Gzip:    ${gzipResult.compressedSize} bytes (${gzipResult.compressionRatio})`);
console.log(`Deflate: ${deflateResult.compressedSize} bytes (${deflateResult.compressionRatio})`);
console.log(`LZ4:     ${lz4Result.compressedSize} bytes (${lz4Result.compressionRatio})`);
console.log(`Snappy:  ${snappyResult.compressedSize} bytes (${snappyResult.compressionRatio})`);

// Verify decompression roundtrip
console.log('Gzip roundtrip:', compress.call('gzipDecompress', gzipResult.data) === testData);
console.log('Deflate roundtrip:', compress.call('deflateDecompress', deflateResult.data) === testData);
console.log('LZ4 roundtrip:', compress.call('lz4Decompress', lz4Result.data) === testData);
console.log('Snappy roundtrip:', compress.call('snappyDecompress', snappyResult.data) === testData);

// Compression toolkit class
import { loadFromGitHub } from 'gowm';

class CompressionToolkit {
  constructor() {
    this.compress = null;
    this.ready = false;
    this.loadModule();
  }

  async loadModule() {
    try {
      this.compress = await loadFromGitHub('benoitpetit/wasm-modules-repository', {
        path: 'compress-wasm',
              name: 'compress-wasm'
      });
      this.compress.call('setSilentMode', true);
      this.ready = true;
    } catch (error) {
      console.error('Failed to load compress module:', error);
    }
  }

  // Auto-select best algorithm
  async smartCompress(data) {
    const analysis = this.compress.call('analyzeCompression', data);
    const best = analysis.bestAlgorithm;

    const compressors = {
      gzip: () => this.compress.call('gzipCompress', data, 9),
      deflate: () => this.compress.call('deflateCompress', data, 9),
      lz4: () => this.compress.call('lz4Compress', data),
      snappy: () => this.compress.call('snappyCompress', data)
    };

    const result = compressors[best]();
    return { ...result, selectedAlgorithm: best, analysis };
  }

  // Create a compressed archive from files
  createArchive(files, format = 'zip') {
    if (format === 'zip') {
      return this.compress.call('zipCreate', files, true);
    } else {
      return this.compress.call('tarCreate', files);
    }
  }
}

const toolkit = new CompressionToolkit();
